import 'dart:io';

/// Stands in for a real generator: writes an empty library naming the file
/// after `--input` to the path after `--output`. Every test here asserts at
/// analysis time, so `:model_g` is never built; the output is written anyway
/// so building it by hand succeeds.
void main(List<String> args) {
  final input = args[args.indexOf('--input') + 1];
  final output = args[args.indexOf('--output') + 1];
  File(output).writeAsStringSync(
    '// Generated by gen.dart from ${input.split('/').last}.\n',
  );
}
